import type { WorkflowTrace } from './trace.ts';

interface Doc {
  fixture: { version: string; seed: number };
  client_timeout_ms: number;
  traces: WorkflowTrace[];
}

/** Human-readable summary of the Phase 03 traces. Generated; do not edit by hand. */
export function renderWorkflowSummary(doc: Doc): string {
  const lines = [
    '# Phase 03 workflow traces (generated)',
    '',
    `Generated by \`npm run traces:workflow\` from fixture \`${doc.fixture.version}\` seed ${doc.fixture.seed}, provider client timeout ${doc.client_timeout_ms} ms. Raw events: [phase-03-workflow-traces.json](phase-03-workflow-traces.json). **Do not edit by hand.**`,
    '',
    'Each scenario: submit → confirm (server-issued token) → worker runs until idle → read back what the customer is told and what both systems actually hold. A **false claim** is `completed` without both systems changed, or `not_changed` when either changed; `needs_review` is conservative, not a confirmation. These are representative traces of variant A, not experimental results.',
    '',
    '| Scenario | Fault | Path through the state machine | Customer told | Order / carrier address | Writes applied (order / carrier) | False claim? |',
    '| --- | --- | --- | --- | --- | --- | --- |',
  ];
  for (const t of doc.traces) {
    const path = t.events.filter((e: { to_status: string | null }) => e.to_status).map((e: { to_status: string }) => e.to_status).join(' → ');
    lines.push(
      `| ${t.scenario_id} ${t.title} | ${t.fault} | ${path}${t.reason ? ` (${t.reason})` : ''} | **${t.customer_told}** | ${t.truth.order.address_id} / ${t.truth.shipment.address_id} | ${t.truth.mutations.order} / ${t.truth.mutations.carrier} | ${t.false_claim ? '**YES**' : 'no'} |`,
    );
  }
  return `${lines.join('\n')}\n`;
}
